function searchBooks(q){
  const tokens=q.toLowerCase().split(/\s+/).filter(Boolean);
  if(!tokens.length)return [];
  const res=[];
  BOOKS.forEach(b=>{
    const title=(b.title||"").toLowerCase();
    const author=(b.author||"").toLowerCase();
    const themes=(b.themes||[]).join(" ").toLowerCase();
    const tags=(b.tags||"").toLowerCase();
    const summary=(b.summary||"").toLowerCase();
    const core=(b.core||[]).join(" \u00b7 ").toLowerCase();
    const hay=[title,author,themes,tags,summary,core];
    let score=0;const where=new Set();
    const ok=tokens.every(t=>{
      let hit=false;
      if(title.includes(t)){hit=true;where.add("title");score+=title===t?100:(title.startsWith(t)?40:title.split(/\s+/).includes(t)?22:12);}
      if(author.includes(t)){hit=true;where.add("author");score+=author.startsWith(t)?30:18;}
      if(themes.includes(t)){hit=true;where.add("theme");score+=14;}
      if(tags.includes(t)){hit=true;where.add("tag");score+=14;}
      if(summary.includes(t)){hit=true;where.add("description");score+=6;}
      if(core.includes(t)){hit=true;where.add("key ideas");score+=5;}
      return hit;
    });
    if(ok)res.push({b,score,where:[...where]});
  });
  return res.sort((a,b)=>b.score-a.score||(b.b.dateRead||"").localeCompare(a.b.dateRead||""));
}
function runSearch(){
  const si=$("#searchInput"); if(!si)return;
  const q=si.value.trim();
  const meta=$("#searchMeta"),box=$("#searchResults");
  if(!q){meta.textContent="";box.innerHTML='<div class="search-empty">Search across titles, authors, themes, tags, and the full text of every description.</div>';return;}
  const tokens=q.toLowerCase().split(/\s+/).filter(Boolean);
  const hits=searchBooks(q);
  meta.textContent=`${hits.length} ${hits.length===1?"match":"matches"} for \u201c${q}\u201d`;
  if(!hits.length){box.innerHTML='<div class="search-empty">No matches. Try a different term \u2014 an author, a theme, or a word from a description.</div>';return;}
  box.innerHTML=hits.slice(0,60).map(({b,where})=>{
    const themeTags=(b.themes||[]).map(t=>`<span class="sr-tag theme" style="background:${THEME_COLORS[t]||'#8a8f98'}">${hl(t,tokens)}</span>`).join("");
    const tagBits=(b.tags||"").split(",").map(s=>s.trim()).filter(Boolean).slice(0,4).map(t=>`<span class="sr-tag">${hl(t,tokens)}</span>`).join("");
    const snip=snippet(b.summary,tokens);
    return `<a class="sr-item" href="${bookHref(b.id)}">
      ${tgCover(b)}
      <div class="sr-body">
        <div class="sr-title">${hl(b.title,tokens)}</div>
        <div class="sr-by">${hl(b.author,tokens)}${b.yearRead?` \u00b7 read ${esc(b.yearRead)}`:""}</div>
        <div class="sr-tags">${themeTags}${tagBits}</div>
        ${snip?`<div class="sr-snip">${snip}</div>`:""}
        <div class="sr-where">matched in ${where.join(" \u00b7 ")}</div>
      </div>
    </a>`;
  }).join("");
}
function openSearch(){const m=$("#searchModal");if(!m)return;m.classList.add("open");loadBooks().then(runSearch);setTimeout(()=>$("#searchInput").focus(),60);}
