/* Replaces a cover <img> with the themed placeholder when the file is absent.
   This is the successor to the deleted probeImg chain: one real request per visible
   cover, no speculative probe, and no Open Library / Google Books fallback. */
function phCover(img) {
  const wrap = img.parentNode;
  if (!wrap) return;
  const b = BOOKS[+img.dataset.i];
  wrap.innerHTML = b ? phHTML(b) : '';
}
window.phCover = phCover;

