/* The Escape key closed three overlays in the SPA; two of them are retired. */
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') { closeSearch(); closeRec(); }
  if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); openSearch(); }
});
window.bookHref = bookHref;
window.loadBooks = loadBooks;
